CREATE TABLE courses (
    id VARCHAR(36) PRIMARY KEY,
    slug VARCHAR(120) NOT NULL UNIQUE,
    payload TEXT NOT NULL,
    status VARCHAR(24) NOT NULL,
    is_demo BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT course_status CHECK (status IN ('DRAFT', 'COMING_SOON', 'PUBLISHED', 'ARCHIVED')),
    CONSTRAINT course_demo_not_saleable CHECK (status <> 'PUBLISHED' OR is_demo = FALSE)
);
CREATE INDEX idx_courses_status_created ON courses (status, created_at);

-- Original curriculum concepts only: not purchasable, no invented reviews or income claims.
INSERT INTO courses (id, slug, payload, status, is_demo, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000101', 'first-link', '{"slug":"first-link","title":"첫 제휴 링크를 만드는 마케터 입문","subtitle":"상품을 고르는 기준부터 솔직한 소개 콘텐츠까지","description":"부추가 준비 중인 부업 입문 강의의 기획 예시입니다. 상품을 고르는 기준부터 솔직한 소개 콘텐츠까지. 정식 강사와 학습 자료가 확정되면 내용과 판매 조건을 안내합니다. 현재는 구매할 수 없으며 수익을 보장하지 않습니다.","category":"AFFILIATE","level":"BEGINNER","status":"COMING_SOON","isDemo":true,"instructorName":"부추 기획팀","instructorBio":"부업을 처음 시작하는 사람을 위한 학습 과정을 기획합니다. 현재 표시된 강의는 출시 전 구성 예시이며, 정식 강사 정보는 출시 시 안내합니다.","thumbnailUrl":"","refundPolicy":"정식 출시 시 안내합니다.","supportEmail":"","price":0,"accessDays":365,"weeklyHours":3,"startupCost":0,"outcomes":["주제에 맞춘 상품 선정 기준표","광고 표시를 포함한 소개 콘텐츠 초안"],"requirements":["인터넷을 사용할 수 있는 PC 또는 휴대폰","직접 경험하거나 조사할 수 있는 관심 분야"],"relatedProgramSlug":"coupang-partners","curriculum":[{"id":"first-link-module-1","title":"제휴마케팅의 구조를 이해하기","lessons":[{"id":"first-link-lesson-1","title":"소개와 구매가 연결되는 과정","durationMinutes":15,"preview":true,"body":"제휴마케팅은 상품이나 서비스를 소개하고 정해진 조건이 충족되면 보상을 받는 방식입니다. 먼저 관심 있는 주제 한 가지를 정하고, 해당 서비스의 참여 조건과 광고 표시 기준을 직접 확인해 보세요. 보상률이나 수익은 서비스와 활동 결과에 따라 달라집니다.","videoUrl":""},{"id":"first-link-lesson-2","title":"광고 표시와 이용 조건 확인하기","durationMinutes":20,"preview":false,"body":"","videoUrl":""}]},{"id":"first-link-module-2","title":"첫 콘텐츠를 설계하기","lessons":[{"id":"first-link-lesson-3","title":"독자를 정하고 상품 후보 비교하기","durationMinutes":25,"preview":false,"body":"","videoUrl":""},{"id":"first-link-lesson-4","title":"소개 글과 링크 배치 점검하기","durationMinutes":30,"preview":false,"body":"","videoUrl":""}]}]}', 'COMING_SOON', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO courses (id, slug, payload, status, is_demo, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000102', 'blog-content', '{"slug":"blog-content","title":"작은 주제로 시작하는 블로그 콘텐츠","subtitle":"내 경험을 검색하는 사람에게 닿는 글로 바꾸기","description":"부추가 준비 중인 부업 입문 강의의 기획 예시입니다. 내 경험을 검색하는 사람에게 닿는 글로 바꾸기. 정식 강사와 학습 자료가 확정되면 내용과 판매 조건을 안내합니다. 현재는 구매할 수 없으며 수익을 보장하지 않습니다.","category":"CONTENT","level":"BEGINNER","status":"COMING_SOON","isDemo":true,"instructorName":"부추 기획팀","instructorBio":"부업을 처음 시작하는 사람을 위한 학습 과정을 기획합니다. 현재 표시된 강의는 출시 전 구성 예시이며, 정식 강사 정보는 출시 시 안내합니다.","thumbnailUrl":"","refundPolicy":"정식 출시 시 안내합니다.","supportEmail":"","price":0,"accessDays":365,"weeklyHours":4,"startupCost":0,"outcomes":["독자 질문을 담은 글감 목록","제목과 본문 구조가 있는 콘텐츠 초안"],"requirements":["글을 발행할 블로그 계정","기록할 수 있는 경험 또는 관심 주제"],"relatedProgramSlug":null,"curriculum":[{"id":"blog-content-module-1","title":"누구에게 쓸지 정하기","lessons":[{"id":"blog-content-lesson-1","title":"경험에서 글감 찾기","durationMinutes":15,"preview":true,"body":"지속할 수 있는 콘텐츠는 익숙한 경험에서 출발합니다. 최근 누군가에게 설명해 준 일을 세 가지 적어 보세요. 각 경험 아래에 독자가 궁금해할 질문을 한 줄씩 쓰면 첫 글의 목적과 범위를 정하는 데 도움이 됩니다.","videoUrl":""},{"id":"blog-content-lesson-2","title":"독자의 질문 모으기","durationMinutes":20,"preview":false,"body":"","videoUrl":""}]},{"id":"blog-content-module-2","title":"읽기 쉬운 글 만들기","lessons":[{"id":"blog-content-lesson-3","title":"도입과 본문 목차 설계하기","durationMinutes":25,"preview":false,"body":"","videoUrl":""},{"id":"blog-content-lesson-4","title":"발행 전 사실과 링크 점검하기","durationMinutes":30,"preview":false,"body":"","videoUrl":""}]}]}', 'COMING_SOON', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO courses (id, slug, payload, status, is_demo, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000103', 'small-store', '{"slug":"small-store","title":"소규모 온라인 판매 준비 노트","subtitle":"재고를 늘리기 전에 판매 구조와 비용부터 확인하기","description":"부추가 준비 중인 부업 입문 강의의 기획 예시입니다. 재고를 늘리기 전에 판매 구조와 비용부터 확인하기. 정식 강사와 학습 자료가 확정되면 내용과 판매 조건을 안내합니다. 현재는 구매할 수 없으며 수익을 보장하지 않습니다.","category":"COMMERCE","level":"BEGINNER","status":"COMING_SOON","isDemo":true,"instructorName":"부추 기획팀","instructorBio":"부업을 처음 시작하는 사람을 위한 학습 과정을 기획합니다. 현재 표시된 강의는 출시 전 구성 예시이며, 정식 강사 정보는 출시 시 안내합니다.","thumbnailUrl":"","refundPolicy":"정식 출시 시 안내합니다.","supportEmail":"","price":0,"accessDays":365,"weeklyHours":5,"startupCost":50000,"outcomes":["상품 후보별 원가와 비용 비교표","판매 준비 단계와 확인 사항 목록"],"requirements":["상품을 조사할 수 있는 PC","샘플·포장 비용을 검토할 예산"],"relatedProgramSlug":null,"curriculum":[{"id":"small-store-module-1","title":"판매 전에 구조 확인하기","lessons":[{"id":"small-store-lesson-1","title":"고객과 상품 후보 정리하기","durationMinutes":15,"preview":true,"body":"온라인 판매를 준비할 때는 판매가만 보기보다 상품 원가, 배송, 포장, 플랫폼 수수료와 반품 가능성을 함께 정리해야 합니다. 관심 상품 한 개를 골라 비용표를 만들어 보세요. 표시된 준비 비용은 학습 계획용 추정치이며 실제 비용은 선택한 상품에 따라 달라집니다.","videoUrl":""},{"id":"small-store-lesson-2","title":"원가와 배송 비용 계산하기","durationMinutes":20,"preview":false,"body":"","videoUrl":""}]},{"id":"small-store-module-2","title":"작게 실험할 준비하기","lessons":[{"id":"small-store-lesson-3","title":"상품 정보와 사진 준비하기","durationMinutes":25,"preview":false,"body":"","videoUrl":""},{"id":"small-store-lesson-4","title":"주문 대응과 재고 계획 세우기","durationMinutes":30,"preview":false,"body":"","videoUrl":""}]}]}', 'COMING_SOON', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO courses (id, slug, payload, status, is_demo, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000104', 'digital-book', '{"slug":"digital-book","title":"내 경험으로 만드는 첫 디지털 자료","subtitle":"작은 문제 하나를 해결하는 전자책과 템플릿 기획","description":"부추가 준비 중인 부업 입문 강의의 기획 예시입니다. 작은 문제 하나를 해결하는 전자책과 템플릿 기획. 정식 강사와 학습 자료가 확정되면 내용과 판매 조건을 안내합니다. 현재는 구매할 수 없으며 수익을 보장하지 않습니다.","category":"DIGITAL","level":"BEGINNER","status":"COMING_SOON","isDemo":true,"instructorName":"부추 기획팀","instructorBio":"부업을 처음 시작하는 사람을 위한 학습 과정을 기획합니다. 현재 표시된 강의는 출시 전 구성 예시이며, 정식 강사 정보는 출시 시 안내합니다.","thumbnailUrl":"","refundPolicy":"정식 출시 시 안내합니다.","supportEmail":"","price":0,"accessDays":365,"weeklyHours":4,"startupCost":0,"outcomes":["대상 독자와 해결 과제가 담긴 기획서","자료의 목차와 샘플 페이지"],"requirements":["문서 편집 도구","직접 정리할 수 있는 지식 또는 경험"],"relatedProgramSlug":null,"curriculum":[{"id":"digital-book-module-1","title":"작은 문제 하나 고르기","lessons":[{"id":"digital-book-lesson-1","title":"경험과 독자 문제 연결하기","durationMinutes":15,"preview":true,"body":"디지털 자료의 범위는 좁게 정할수록 첫 결과물을 완성하기 쉽습니다. 자신이 직접 해 본 일 가운데 다른 사람의 시간을 줄여 줄 수 있는 절차를 하나 골라 보세요. 그 사람이 자료를 읽은 뒤 바로 할 수 있는 행동을 한 문장으로 적어 봅니다.","videoUrl":""},{"id":"digital-book-lesson-2","title":"자료의 범위와 목차 정하기","durationMinutes":20,"preview":false,"body":"","videoUrl":""}]},{"id":"digital-book-module-2","title":"쓸 수 있는 자료 만들기","lessons":[{"id":"digital-book-lesson-3","title":"샘플 페이지 구성하기","durationMinutes":25,"preview":false,"body":"","videoUrl":""},{"id":"digital-book-lesson-4","title":"출처와 사용 권한 점검하기","durationMinutes":30,"preview":false,"body":"","videoUrl":""}]}]}', 'COMING_SOON', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO courses (id, slug, payload, status, is_demo, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000105', 'freelance-start', '{"slug":"freelance-start","title":"재능을 서비스로 만드는 프리랜서 시작","subtitle":"업무 범위와 결과물을 명확하게 제안하는 연습","description":"부추가 준비 중인 부업 입문 강의의 기획 예시입니다. 업무 범위와 결과물을 명확하게 제안하는 연습. 정식 강사와 학습 자료가 확정되면 내용과 판매 조건을 안내합니다. 현재는 구매할 수 없으며 수익을 보장하지 않습니다.","category":"SERVICE","level":"BEGINNER","status":"COMING_SOON","isDemo":true,"instructorName":"부추 기획팀","instructorBio":"부업을 처음 시작하는 사람을 위한 학습 과정을 기획합니다. 현재 표시된 강의는 출시 전 구성 예시이며, 정식 강사 정보는 출시 시 안내합니다.","thumbnailUrl":"","refundPolicy":"정식 출시 시 안내합니다.","supportEmail":"","price":0,"accessDays":365,"weeklyHours":3,"startupCost":0,"outcomes":["작업 범위와 납품물을 담은 서비스 소개서","예상 소요 시간과 견적 계산표"],"requirements":["직접 제공할 수 있는 기술 또는 경험","샘플 작업에 사용할 PC와 도구"],"relatedProgramSlug":null,"curriculum":[{"id":"freelance-start-module-1","title":"제공할 서비스를 좁히기","lessons":[{"id":"freelance-start-lesson-1","title":"기술을 구체적인 결과물로 표현하기","durationMinutes":15,"preview":true,"body":"서비스를 소개할 때는 잘하는 일을 나열하는 것보다 고객이 받게 될 결과물을 구체적으로 적는 편이 좋습니다. 작업 범위, 제공 파일, 일정, 수정 가능 범위를 표로 정리해 보세요. 실제 제안 전에는 필요한 자료와 합의할 조건을 함께 확인합니다.","videoUrl":""},{"id":"freelance-start-lesson-2","title":"대상 고객과 작업 범위 정하기","durationMinutes":20,"preview":false,"body":"","videoUrl":""}]},{"id":"freelance-start-module-2","title":"첫 제안 준비하기","lessons":[{"id":"freelance-start-lesson-3","title":"샘플과 견적 근거 만들기","durationMinutes":25,"preview":false,"body":"","videoUrl":""},{"id":"freelance-start-lesson-4","title":"수정 횟수와 납기 안내하기","durationMinutes":30,"preview":false,"body":"","videoUrl":""}]}]}', 'COMING_SOON', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO courses (id, slug, payload, status, is_demo, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000106', 'ai-workflow', '{"slug":"ai-workflow","title":"반복 작업을 줄이는 AI 부업 워크플로","subtitle":"초안 작성과 검토를 나눠 더 꾸준하게 작업하기","description":"부추가 준비 중인 부업 입문 강의의 기획 예시입니다. 초안 작성과 검토를 나눠 더 꾸준하게 작업하기. 정식 강사와 학습 자료가 확정되면 내용과 판매 조건을 안내합니다. 현재는 구매할 수 없으며 수익을 보장하지 않습니다.","category":"AI","level":"BEGINNER","status":"COMING_SOON","isDemo":true,"instructorName":"부추 기획팀","instructorBio":"부업을 처음 시작하는 사람을 위한 학습 과정을 기획합니다. 현재 표시된 강의는 출시 전 구성 예시이며, 정식 강사 정보는 출시 시 안내합니다.","thumbnailUrl":"","refundPolicy":"정식 출시 시 안내합니다.","supportEmail":"","price":0,"accessDays":365,"weeklyHours":3,"startupCost":0,"outcomes":["반복 작업을 나눈 업무 흐름도","검토 기준이 포함된 프롬프트와 체크리스트"],"requirements":["사용 조건을 확인한 AI 도구 계정","작업 결과를 직접 검토할 기본 지식"],"relatedProgramSlug":null,"curriculum":[{"id":"ai-workflow-module-1","title":"자동화할 일 찾기","lessons":[{"id":"ai-workflow-lesson-1","title":"반복 작업과 판단 작업 나누기","durationMinutes":15,"preview":true,"body":"AI 도구를 활용할 때는 어떤 작업을 맡기고 무엇을 직접 확인할지 먼저 구분해 보세요. 예를 들어 글의 목차는 초안으로 받아도 사실, 출처, 고객 정보의 취급은 직접 검토해야 합니다. 민감한 정보를 입력하지 않는 작은 연습 과제부터 시작합니다.","videoUrl":""},{"id":"ai-workflow-lesson-2","title":"도구의 이용 조건과 정보 입력 범위 확인하기","durationMinutes":20,"preview":false,"body":"","videoUrl":""}]},{"id":"ai-workflow-module-2","title":"검토 가능한 흐름 만들기","lessons":[{"id":"ai-workflow-lesson-3","title":"작은 초안 작업부터 프롬프트 설계하기","durationMinutes":25,"preview":false,"body":"","videoUrl":""},{"id":"ai-workflow-lesson-4","title":"사실 확인과 최종 수정 단계 넣기","durationMinutes":30,"preview":false,"body":"","videoUrl":""}]}]}', 'COMING_SOON', TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
